import unittest
from bands import band

class Bands(unittest.TestCase):
    def test_boundaries(self):
        for width, expected in [(0,'letter'),(23,'letter'),(24,'letter'),(25,'packet'),(75,'packet'),(76,'packet'),(77,'parcel'),(1000,'parcel')]:
            with self.subTest(width=width):
                self.assertEqual(band(width), expected)
    def test_negative(self):
        for width in [-1, -80]:
            with self.assertRaises(ValueError): band(width)

if __name__ == '__main__':
    unittest.main()

